let stageVisible=true, frameId=null;
function requestScene(force=false){
 if(!ctx)return;
 if(frameId!==null)cancelAnimationFrame(frameId);
 frameId=null;
 // Commit explicit navigation/resize changes immediately; WebKit can defer offscreen RAF.
 if(force){renderScene(performance.now(),true);return;}
 if(!stageVisible||document.hidden||document.body.classList.contains('resources-open')||$('detail-dialog').open)return;
 frameId=requestAnimationFrame(renderScene);
}
if('IntersectionObserver' in window)new IntersectionObserver(entries=>{
 if(entries[0])stageVisible=entries[0].isIntersecting;
 if(stageVisible)requestScene(true);else if(frameId!==null){cancelAnimationFrame(frameId);frameId=null;}
},{rootMargin:'0px'}).observe($('scene-frame'));
document.addEventListener('visibilitychange',()=>requestScene());
function renderScene(ts,forced=false){frameId=null;if(!ctx)return;if(!forced&&(!stageVisible||document.hidden||document.body.classList.contains('resources-open')||$('detail-dialog').open))return;if(!forced&&ts-(s.lastDraw||0)<28){requestScene();return;}s.lastDraw=ts;world.render(ts,s.motion);s.w=canvas.clientWidth;s.h=canvas.clientHeight;placeHotspots();canvas.dataset.renderedRoom=s.room;requestScene();}
function resize(){s.w=canvas.clientWidth;s.h=canvas.clientHeight;if(!ctx){$('scene-frame').classList.add('without-webgl');canvas.hidden=true;document.getElementById('graphics-notice').hidden=false;}requestScene(true);}
if('ResizeObserver'in window)new ResizeObserver(resize).observe(canvas);
window.addEventListener('resize',resize);
$('motion-btn').addEventListener('click',()=>requestScene(true));
