const motionPreference=matchMedia('(prefers-reduced-motion:reduce)');
motionPreference.addEventListener?.('change',e=>{s.motion=!e.matches;$('motion-btn').textContent=s.motion?'Ⅱ':'▶';$('motion-btn').setAttribute('aria-pressed',String(!s.motion));localized();requestScene(true)});
// News cards use already published real site posts; when possible, load the latest public WP entries without author credentials.
async function syncPublicNews(){const abort=new AbortController();const timer=setTimeout(()=>abort.abort(),3500);try{const res=await fetch('https://public-api.wordpress.com/rest/v1.1/sites/alirezamalakootikhah.wordpress.com/posts/?number=5&fields=title,URL,date,excerpt', {signal:abort.signal});clearTimeout(timer);if(!res.ok)return;const json=await res.json();const entries=(json.posts||[]).filter(x=>/^https:\/\/alirezamalakootikhah\.wordpress\.com\//.test(x.URL||''));let added=0;entries.forEach((p,i)=>{let id='live-news-'+i;if(D.items.some(x=>x.id===id))return;const title=String(p.title||'').replace(/<[^>]+>/g,'').slice(0,160);const text=String(p.excerpt||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').slice(0,190);if(!title)return;D.items.push({id,room:'news',type:'notice',symbol:'✎',category:'article',title:TL(title,title,title),summary:TL(text,text,text),points:TL([String((p.date||'').slice(0,10)),'Read original article','Check the date on the source'],[String((p.date||'').slice(0,10)),'مقاله اصلی را بخوانید','تاریخ را در منبع چک کنید'],[String((p.date||'').slice(0,10)),'اقرأ المقال الأصلي','تحقق من تاريخ المصدر']),url:p.URL});added++});if(s.room==='news'&&added)renderCollection()}catch(e){/* Static articles remain available without remote API */}finally{clearTimeout(timer)}}
